// MinecraftManager.js - Implementação de funcionalidades para Minecraft
const { execSync } = require('child_process');
const path = require('path');

class MinecraftManager {
  constructor() {
    this.minecraftPath = this.findMinecraftPath();
  }

  findMinecraftPath() {
    // Lógica para encontrar o caminho do Minecraft (pode variar por SO)
    // Placeholder - implementar conforme necessário
    return process.env.MINECRAFT_PATH || '';
  }

  async analyzeLog(logFilePath) {
    try {
      if (!logFilePath || !require('fs').existsSync(logFilePath)) {
        throw new Error('Arquivo de log não encontrado');
      }
      const logContent = require('fs').readFileSync(logFilePath, 'utf8');
      // Análise básica do log - pode ser expandida
      const errors = logContent.match(/\[(\d{2}:\d{2}:\d{2})\] \[.*?\] \[.*?\] (ERROR|Exception)/g) || [];
      const warnings = logContent.match(/\[(\d{2}:\d{2}:\d{2})\] \[.*?\] \[.*?\] (WARN)/g) || [];
      return {
        totalLines: logContent.split('\n').length,
        errors: errors.length,
        warnings: warnings.length,
        errorSamples: errors.slice(0, 3),
        warningSamples: warnings.slice(0, 3)
      };
    } catch (error) {
      throw new Error(`Erro ao analisar log: ${error.message}`);
    }
  }

  async listMods(modsFolderPath) {
    try {
      if (!modsFolderPath || !require('fs').existsSync(modsFolderPath)) {
        throw new Error('Pasta de mods não encontrada');
      }
      const files = require('fs').readdirSync(modsFolderPath);
      const mods = files.filter(file => file.endsWith('.jar') || file.endsWith('.zip'));
      return mods.map(mod => ({
        name: mod,
        path: path.join(modsFolderPath, mod),
        size: require('fs').statSync(path.join(modsFolderPath, mod)).size
      }));
    } catch (error) {
      throw new Error(`Erro ao listar mods: ${error.message}`);
    }
  }

  async diagnostic() {
    try {
      const diagnostics = {
        minecraftPath: this.minecraftPath,
        pathExists: !!this.minecraftPath && require('fs').existsSync(this.minecraftPath),
        version: 'Não detectado', // Placeholder
        mods: [],
        resourcePacks: [],
        issues: []
      };

      if (diagnostics.pathExists) {
        // Verificar mods
        const modsPath = path.join(this.minecraftPath, 'mods');
        if (require('fs').existsSync(modsPath)) {
          diagnostics.mods = await this.listMods(modsPath);
        }

        // Verificar resource packs
        const resourcePacksPath = path.join(this.minecraftPath, 'resourcepacks');
        if (require('fs').existsSync(resourcePacksPath)) {
          const packs = require('fs').readdirSync(resourcePacksPath);
          diagnostics.resourcePacks = packs.map(pack => ({
            name: pack,
            path: path.join(resourcePacksPath, pack)
          }));
        }

        // Verificar problemas comuns
        if (!diagnostics.pathExists) {
          diagnostics.issues.push('Caminho do Minecraft não configurado ou não encontrado');
        }
        if (diagnostics.mods.length === 0 && require('fs').existsSync(path.join(this.minecraftPath, 'mods'))) {
          diagnostics.issues.push('Pasta de mods existe mas está vazia');
        }
      }

      return diagnostics;
    } catch (error) {
      throw new Error(`Erro ao gerar diagnóstico: ${error.message}`);
    }
  }

  async disableMod(modName, modsFolderPath) {
    try {
      if (!modsFolderPath || !require('fs').existsSync(modsFolderPath)) {
        throw new Error('Pasta de mods não encontrada');
      }
      const modPath = path.join(modsFolderPath, modName);
      const disabledPath = `${modPath}.disabled`;

      if (!require('fs').existsSync(modPath)) {
        throw new Error(`Mod não encontrado: ${modName}`);
      }

      require('fs').renameSync(modPath, disabledPath);
      return { success: true, message: `Mod ${modName} desativado com sucesso` };
    } catch (error) {
      throw new Error(`Erro ao desativar mod: ${error.message}`);
    }
  }

  async enableMod(modName, modsFolderPath) {
    try {
      if (!modsFolderPath || !require('fs').existsSync(modsFolderPath)) {
        throw new Error('Pasta de mods não encontrada');
      }
      const disabledPath = path.join(modsFolderPath, `${modName}.disabled`);
      const modPath = path.join(modsFolderPath, modName);

      if (!require('fs').existsSync(disabledPath)) {
        throw new Error(`Mod desativado não encontrado: ${modName}`);
      }

      require('fs').renameSync(disabledPath, modPath);
      return { success: true, message: `Mod ${modName} ativado com sucesso` };
    } catch (error) {
      throw new Error(`Erro ao ativar mod: ${error.message}`);
    }
  }
}

module.exports = new MinecraftManager();
